CREATE TABLE IF NOT EXISTS public.aluno_portal_sessions (
    id text NOT NULL,
    email text NOT NULL,
    nome text DEFAULT ''::text NOT NULL,
    foto text,
    expires_at timestamp with time zone NOT NULL,
    criado_em timestamp with time zone DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.atividades_sala (
    id integer NOT NULL,
    codturma text NOT NULL,
    codmatrizaluno text NOT NULL,
    data date NOT NULL,
    nome_aluno text DEFAULT ''::text NOT NULL,
    num_chamada integer,
    atividades jsonb DEFAULT '{}'::jsonb NOT NULL,
    observacao text DEFAULT ''::text NOT NULL,
    criado_em timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now()
);
CREATE SEQUENCE IF NOT EXISTS public.atividades_sala_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;
ALTER SEQUENCE public.atividades_sala_id_seq OWNED BY public.atividades_sala.id;
CREATE TABLE IF NOT EXISTS public.classroom_ausencias (
    id integer NOT NULL,
    curso_id text NOT NULL,
    atividade_id text NOT NULL,
    user_id text NOT NULL,
    nome_aluno text,
    data_atividade text,
    cod_classe text,
    criado_em timestamp with time zone DEFAULT now()
);
CREATE SEQUENCE IF NOT EXISTS public.classroom_ausencias_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;
ALTER SEQUENCE public.classroom_ausencias_id_seq OWNED BY public.classroom_ausencias.id;
CREATE TABLE IF NOT EXISTS public.classroom_grupo_atividades (
    id integer NOT NULL,
    grupo_id integer NOT NULL,
    atividade_id text NOT NULL,
    atividade_titulo text DEFAULT ''::text NOT NULL,
    pontos_max numeric
);
CREATE SEQUENCE IF NOT EXISTS public.classroom_grupo_atividades_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;
ALTER SEQUENCE public.classroom_grupo_atividades_id_seq OWNED BY public.classroom_grupo_atividades.id;
CREATE TABLE IF NOT EXISTS public.classroom_grupos (
    id integer NOT NULL,
    curso_id text NOT NULL,
    nome text NOT NULL,
    pontos_meta numeric DEFAULT 40 NOT NULL,
    cor text DEFAULT '#4285F4'::text NOT NULL,
    criado_em timestamp with time zone DEFAULT now()
);
CREATE SEQUENCE IF NOT EXISTS public.classroom_grupos_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;
ALTER SEQUENCE public.classroom_grupos_id_seq OWNED BY public.classroom_grupos.id;
CREATE TABLE IF NOT EXISTS public.edusync_audit_log (
    id integer NOT NULL,
    usuario_id integer,
    usuario_nome character varying(100),
    acao character varying(100) NOT NULL,
    modulo character varying(50),
    detalhes jsonb,
    ip character varying(45),
    criado_em timestamp without time zone DEFAULT now() NOT NULL
);
CREATE SEQUENCE IF NOT EXISTS public.edusync_audit_log_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;
ALTER SEQUENCE public.edusync_audit_log_id_seq OWNED BY public.edusync_audit_log.id;
CREATE TABLE IF NOT EXISTS public.edusync_escolas (
    id integer NOT NULL,
    nome character varying(200) NOT NULL,
    codigo_estabelecimento integer NOT NULL,
    permite_auto_cadastro boolean DEFAULT true NOT NULL,
    ativo boolean DEFAULT true NOT NULL,
    criado_em timestamp without time zone DEFAULT now() NOT NULL
);
CREATE SEQUENCE IF NOT EXISTS public.edusync_escolas_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;
ALTER SEQUENCE public.edusync_escolas_id_seq OWNED BY public.edusync_escolas.id;
CREATE TABLE IF NOT EXISTS public.edusync_usuarios (
    id integer NOT NULL,
    nome character varying(100) NOT NULL,
    cpf character varying(11) NOT NULL,
    perfil character varying(20) DEFAULT 'professor'::character varying NOT NULL,
    ativo boolean DEFAULT true NOT NULL,
    criado_em timestamp without time zone DEFAULT now() NOT NULL,
    criado_por integer
);
CREATE SEQUENCE IF NOT EXISTS public.edusync_usuarios_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;
ALTER SEQUENCE public.edusync_usuarios_id_seq OWNED BY public.edusync_usuarios.id;
CREATE TABLE IF NOT EXISTS public.livros_didaticos (
    id integer NOT NULL,
    titulo character varying(200) NOT NULL,
    autor character varying(200),
    editora character varying(150),
    ano_publicacao integer,
    disciplina character varying(100),
    serie character varying(80),
    isbn character varying(20),
    quantidade integer DEFAULT 1 NOT NULL,
    ativo boolean DEFAULT true NOT NULL,
    criado_em timestamp without time zone DEFAULT now() NOT NULL
);
CREATE SEQUENCE IF NOT EXISTS public.livros_didaticos_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;
ALTER SEQUENCE public.livros_didaticos_id_seq OWNED BY public.livros_didaticos.id;
CREATE TABLE IF NOT EXISTS public.livros_emprestimos (
    id integer NOT NULL,
    livro_id integer NOT NULL,
    cod_matriz_aluno integer NOT NULL,
    nome_aluno character varying(200),
    turma character varying(150),
    num_chamada integer,
    ano_letivo integer DEFAULT EXTRACT(year FROM now()) NOT NULL,
    status character varying(20) DEFAULT 'emprestado'::character varying NOT NULL,
    data_emprestimo timestamp without time zone DEFAULT now() NOT NULL,
    data_devolucao timestamp without time zone,
    obs text,
    criado_em timestamp without time zone DEFAULT now() NOT NULL
);
CREATE SEQUENCE IF NOT EXISTS public.livros_emprestimos_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;
ALTER SEQUENCE public.livros_emprestimos_id_seq OWNED BY public.livros_emprestimos.id;
CREATE TABLE IF NOT EXISTS public.mapa_sala (
    id integer NOT NULL,
    codturma bigint NOT NULL,
    turma text NOT NULL,
    colunas integer DEFAULT 5 NOT NULL,
    filas integer DEFAULT 6 NOT NULL,
    posicoes jsonb DEFAULT '[]'::jsonb NOT NULL,
    alunos_fora jsonb DEFAULT '[]'::jsonb NOT NULL,
    criado_em timestamp with time zone DEFAULT now(),
    atualizado_em timestamp with time zone DEFAULT now()
);
CREATE SEQUENCE IF NOT EXISTS public.mapa_sala_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;
ALTER SEQUENCE public.mapa_sala_id_seq OWNED BY public.mapa_sala.id;
CREATE TABLE IF NOT EXISTS public.ocorrencia_meta (
    id_ocorrencia text NOT NULL,
    professor_nome text DEFAULT ''::text NOT NULL,
    nome_turma text DEFAULT ''::text NOT NULL,
    criado_em timestamp with time zone DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.pedagogo_notas (
    id_ocorrencia text NOT NULL,
    nota text DEFAULT ''::text NOT NULL,
    encaminhamento text DEFAULT ''::text NOT NULL,
    visto boolean DEFAULT false NOT NULL,
    visto_em timestamp with time zone,
    criado_em timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    visto_professor boolean DEFAULT false NOT NULL,
    visto_prof_em timestamp with time zone
);
CREATE TABLE IF NOT EXISTS public.rco_classes (
    cod_classe integer NOT NULL,
    cod_turma integer,
    cod_disciplina integer,
    cod_estabelecimento integer,
    periodo_letivo text,
    atualizado_em timestamp with time zone DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.rco_disciplinas (
    cod_disciplina integer NOT NULL,
    nome_disciplina text NOT NULL,
    sigla text,
    cor_fundo text,
    cor_letra text,
    atualizado_em timestamp with time zone DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.rco_estabelecimentos (
    cod_estabelecimento integer NOT NULL,
    nome_estabelecimento text NOT NULL,
    cod_municipio integer,
    atualizado_em timestamp with time zone DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.rco_turmas (
    cod_turma integer NOT NULL,
    descr_turma text NOT NULL,
    cod_seriacao integer,
    cod_estabelecimento integer,
    periodo_letivo text,
    atualizado_em timestamp with time zone DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.rco_sync_log (
    id integer NOT NULL,
    executado_em timestamp with time zone DEFAULT now(),
    status text NOT NULL,
    estabelecimentos integer DEFAULT 0,
    turmas integer DEFAULT 0,
    disciplinas integer DEFAULT 0,
    classes integer DEFAULT 0,
    mensagem text
);
CREATE SEQUENCE IF NOT EXISTS public.rco_sync_log_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;
ALTER SEQUENCE public.rco_sync_log_id_seq OWNED BY public.rco_sync_log.id;
ALTER TABLE ONLY public.atividades_sala ALTER COLUMN id SET DEFAULT nextval('public.atividades_sala_id_seq'::regclass);
ALTER TABLE ONLY public.classroom_ausencias ALTER COLUMN id SET DEFAULT nextval('public.classroom_ausencias_id_seq'::regclass);
ALTER TABLE ONLY public.classroom_grupo_atividades ALTER COLUMN id SET DEFAULT nextval('public.classroom_grupo_atividades_id_seq'::regclass);
ALTER TABLE ONLY public.classroom_grupos ALTER COLUMN id SET DEFAULT nextval('public.classroom_grupos_id_seq'::regclass);
ALTER TABLE ONLY public.edusync_audit_log ALTER COLUMN id SET DEFAULT nextval('public.edusync_audit_log_id_seq'::regclass);
ALTER TABLE ONLY public.edusync_escolas ALTER COLUMN id SET DEFAULT nextval('public.edusync_escolas_id_seq'::regclass);
ALTER TABLE ONLY public.edusync_usuarios ALTER COLUMN id SET DEFAULT nextval('public.edusync_usuarios_id_seq'::regclass);
ALTER TABLE ONLY public.livros_didaticos ALTER COLUMN id SET DEFAULT nextval('public.livros_didaticos_id_seq'::regclass);
ALTER TABLE ONLY public.livros_emprestimos ALTER COLUMN id SET DEFAULT nextval('public.livros_emprestimos_id_seq'::regclass);
ALTER TABLE ONLY public.mapa_sala ALTER COLUMN id SET DEFAULT nextval('public.mapa_sala_id_seq'::regclass);
ALTER TABLE ONLY public.rco_sync_log ALTER COLUMN id SET DEFAULT nextval('public.rco_sync_log_id_seq'::regclass);
