    ADD CONSTRAINT atividades_sala_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.classroom_ausencias
    ADD CONSTRAINT classroom_ausencias_curso_id_atividade_id_user_id_key UNIQUE (curso_id, atividade_id, user_id);
ALTER TABLE ONLY public.classroom_ausencias
    ADD CONSTRAINT classroom_ausencias_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.classroom_grupo_atividades
    ADD CONSTRAINT classroom_grupo_atividades_grupo_id_atividade_id_key UNIQUE (grupo_id, atividade_id);
ALTER TABLE ONLY public.classroom_grupo_atividades
    ADD CONSTRAINT classroom_grupo_atividades_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.classroom_grupos
    ADD CONSTRAINT classroom_grupos_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.edusync_audit_log
    ADD CONSTRAINT edusync_audit_log_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.edusync_escolas
    ADD CONSTRAINT edusync_escolas_codigo_estabelecimento_key UNIQUE (codigo_estabelecimento);
ALTER TABLE ONLY public.edusync_escolas
    ADD CONSTRAINT edusync_escolas_pkey PRIMARY KEY (id);
