    ADD CONSTRAINT edusync_usuarios_cpf_key UNIQUE (cpf);
ALTER TABLE ONLY public.edusync_usuarios
    ADD CONSTRAINT edusync_usuarios_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.livros_didaticos
    ADD CONSTRAINT livros_didaticos_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.livros_emprestimos
    ADD CONSTRAINT livros_emprestimos_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.mapa_sala
    ADD CONSTRAINT mapa_sala_codturma_key UNIQUE (codturma);
ALTER TABLE ONLY public.mapa_sala
    ADD CONSTRAINT mapa_sala_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.ocorrencia_meta
    ADD CONSTRAINT ocorrencia_meta_pkey PRIMARY KEY (id_ocorrencia);
ALTER TABLE ONLY public.pedagogo_notas
    ADD CONSTRAINT pedagogo_notas_pkey PRIMARY KEY (id_ocorrencia);
ALTER TABLE ONLY public.rco_classes
    ADD CONSTRAINT rco_classes_pkey PRIMARY KEY (cod_classe);
ALTER TABLE ONLY public.rco_disciplinas
    ADD CONSTRAINT rco_disciplinas_pkey PRIMARY KEY (cod_disciplina);
ALTER TABLE ONLY public.rco_estabelecimentos
    ADD CONSTRAINT rco_estabelecimentos_pkey PRIMARY KEY (cod_estabelecimento);
