    ADD CONSTRAINT rco_turmas_pkey PRIMARY KEY (cod_turma);
CREATE INDEX IF NOT EXISTS idx_audit_log_criado ON public.edusync_audit_log USING btree (criado_em DESC);
CREATE INDEX IF NOT EXISTS idx_audit_log_usuario ON public.edusync_audit_log USING btree (usuario_id);
CREATE INDEX IF NOT EXISTS idx_emp_aluno ON public.livros_emprestimos USING btree (cod_matriz_aluno);
CREATE INDEX IF NOT EXISTS idx_emp_livro ON public.livros_emprestimos USING btree (livro_id);
CREATE INDEX IF NOT EXISTS idx_emp_status ON public.livros_emprestimos USING btree (status);
ALTER TABLE ONLY public.classroom_grupo_atividades
    ADD CONSTRAINT classroom_grupo_atividades_grupo_id_fkey FOREIGN KEY (grupo_id) REFERENCES public.classroom_grupos(id) ON DELETE CASCADE;
ALTER TABLE ONLY public.edusync_audit_log
    ADD CONSTRAINT edusync_audit_log_usuario_id_fkey FOREIGN KEY (usuario_id) REFERENCES public.edusync_usuarios(id);
ALTER TABLE ONLY public.edusync_usuarios
    ADD CONSTRAINT edusync_usuarios_criado_por_fkey FOREIGN KEY (criado_por) REFERENCES public.edusync_usuarios(id);
ALTER TABLE ONLY public.livros_emprestimos
    ADD CONSTRAINT livros_emprestimos_livro_id_fkey FOREIGN KEY (livro_id) REFERENCES public.livros_didaticos(id);
ALTER TABLE ONLY public.rco_classes
    ADD CONSTRAINT rco_classes_cod_disciplina_fkey FOREIGN KEY (cod_disciplina) REFERENCES public.rco_disciplinas(cod_disciplina);
ALTER TABLE ONLY public.rco_classes
    ADD CONSTRAINT rco_classes_cod_estabelecimento_fkey FOREIGN KEY (cod_estabelecimento) REFERENCES public.rco_estabelecimentos(cod_estabelecimento);
ALTER TABLE ONLY public.rco_classes
    ADD CONSTRAINT rco_classes_cod_turma_fkey FOREIGN KEY (cod_turma) REFERENCES public.rco_turmas(cod_turma);
ALTER TABLE ONLY public.rco_turmas
    ADD CONSTRAINT rco_turmas_cod_estabelecimento_fkey FOREIGN KEY (cod_estabelecimento) REFERENCES public.rco_estabelecimentos(cod_estabelecimento);
CREATE POLICY leitura_publica ON public.rco_classes FOR SELECT USING (true);
CREATE POLICY leitura_publica ON public.rco_disciplinas FOR SELECT USING (true);
CREATE POLICY leitura_publica ON public.rco_estabelecimentos FOR SELECT USING (true);
CREATE POLICY leitura_publica ON public.rco_sync_log FOR SELECT USING (true);
CREATE POLICY leitura_publica ON public.rco_turmas FOR SELECT USING (true);
